def archive_info(database:Database,archive_case:dict)-> dict:
    data = {
        'collaborators': archive_case['collaborators'],
        'synopsis': archive_case.get('synopsis'),
        'assignees': [],
        'suspects': [],
        'causatives': [],
        'phenotype_terms': [],
        'phenotype_groups': []
    }

